  "page28": {
    "html_title": "Notifications (Web) — Facil Manual",
    "title": "Notifications — receiving updates",
    "description": "Facil keeps you informed by email on every status change of your requests: receipt, pending payment, validation, completion. PDF receipts are attached directly to the emails for immediate access.",
    "next": "Next: AI Assistant and Support →",
    "prev": "← Previous: My companies",
    "toc": {
      "s1": "1. Email notification types",
      "s2": "2. «Request Received» email",
      "s3": "3. «Payment Pending» email",
      "s4": "4. «Payment Validated» email",
      "s5": "5. Public verification from email",
      "s6": "6. Configure preferences"
    },
    "s1": {
      "title": "1. Email notification types",
      "intro": "Each Facil email has a <strong>header color</strong> based on the event type — so you can identify it instantly:",
      "f1": "<span style=\"color:#FFA500\">🟠</span> <strong>Orange</strong> — Action required (pending payment, document requested by agent)",
      "f2": "<span style=\"color:#0062A5\">🔵</span> <strong>Blue</strong> — Information (request received, appointment scheduled, status change)",
      "f3": "<span style=\"color:#009A44\">🟢</span> <strong>Green</strong> — Validation / success (payment validated, procedure completed, document ready)",
      "f4": "<span style=\"color:#D22630\">🔴</span> <strong>Red</strong> — Security alert (password change, suspicious sign-in) or rejection",
      "body": "The sender is always <code>noreply@taxasge.emacsah.com</code>. If you receive a Facil email from another sender, it is <strong>phishing</strong> — do not click on the links."
    },
    "s2": {
      "title": "2. «Request Received» email",
      "intro": "Sent immediately after your request is created. Green header, «Request Received» message, name + reference + list of next steps.",
      "fig1": {
        "alt": "Request Received email",
        "caption": "«Request Received» email — header «Request Received», «Hello libre Gmil», Reference CON-2026-00001, next steps (reviewed / we will notify you / we will contact you), attachment <code>solicitud_CON-...00001.pdf</code> with preview visible."
      }
    },
    "s3": {
      "title": "3. «Payment Pending» email",
      "intro": "Sent in the case of cash or cheque payment after request creation. Gives you instructions to finalize the payment at an office.",
      "fig1": {
        "alt": "Gmail inbox with 3 emails",
        "caption": "Gmail inbox — 3 TaxasGE Platform emails: «Cash payment validated» 17:07, «Request received» 15:05, «Cash payment pending» 15:05."
      },
      "fig2": {
        "alt": "Payment Pending email",
        "caption": "«Cash Payment Pending» email (orange header) — details (Ref CSH-..., 25,000 XAF, Cash) + «Next steps» section in 4 stages (Go to office / Present ref / Make payment / Agent validates)."
      }
    },
    "s4": {
      "title": "4. «Payment Validated» email",
      "intro": "Sent after agent validation. Green header, PDF receipt as attachment, public verification link.",
      "fig1": {
        "alt": "Payment Validated email split",
        "caption": "«Cash Payment Validated» email (green header) — details (Request CON-2026-00001, Ref CSH-..., 25,000 XAF, Cash, Receipt REC-2026-000013, Date 2026-04-19)."
      },
      "fig2": {
        "alt": "Email scroll bottom",
        "caption": "Continuation of «Payment Validated» email — Next steps section «Your request will continue processing», «Verify receipt authenticity» link → verify URL, attachment <code>recibo_REC-...000013.pdf</code> with preview Treasury Receipt Malabo."
      }
    },
    "s5": {
      "title": "5. Public verification from email",
      "intro": "Each email contains a <strong>«Verify receipt authenticity»</strong> link that opens directly the <a href=\"57-verificar.html\">public verification page</a> with the corresponding reference and token. Useful when a third party (bank, embassy) asks you for proof — just share the link.",
      "fig1": {
        "alt": "Verify receipt page from email",
        "caption": "Verify receipt page (URL <code>/es/verify/REC-2026-...</code>) opened from the email link — green «Valid Receipt» badge, Number REC-2026-000013, date, amount 25,000 XAF Cash, payer, code CONDUCIR_RENOVACION, entity DGT, ref CON-2026-00001."
      }
    },
    "s6": {
      "title": "6. Configure preferences",
      "intro": "Notification preferences are configured from your <a href=\"15-perfil.html\">Profile</a> → «Notifications» tab. 3 adjustable channels:",
      "f1": "<strong>Email</strong> (on by default, cannot be disabled for critical alerts)",
      "f2": "<strong>Push notifications</strong> (mobile only)",
      "f3": "<strong>SMS</strong> (optional, cost charged by the operator)",
      "body": "The notification language (ES/FR/EN) is based on the preference set in your profile. If you change your preferred language, future notifications will be sent in the new language.",
      "tip": "If you do not receive the emails, <strong>always check the spam folder</strong> first. Add <code>noreply@taxasge.emacsah.com</code> to your contacts to avoid filtering. For persistent problems, contact <a href=\"29-soporte-web.html\">support</a>.",
      "success": "Email notifications are the backbone of communication with Facil — data is always available on the dashboard too, emails are a complementary channel."
    }
  },
